"""Shared exceptions for minisql."""


class QueryError(Exception):
    """Raised for any problem with a query."""

"""Tokenizer and parser for the minisql SELECT dialect."""

from dataclasses import dataclass, field
from typing import Any, List, Optional

from ._errors import QueryError


KEYWORDS = {
    "SELECT", "DISTINCT", "FROM", "WHERE", "GROUP", "BY", "HAVING",
    "ORDER", "LIMIT", "OFFSET", "AS", "ASC", "DESC", "AND", "OR",
    "NOT", "IN", "BETWEEN", "LIKE", "IS", "NULL", "TRUE", "FALSE",
}

_COMPARISON_OPS = {"=", "!=", "<>", "<", "<=", ">", ">="}


# ---------------------------------------------------------------------------
# Tokens


@dataclass
class Token:
    kind: str
    value: Any
    start: int
    end: int


def tokenize(sql):
    """Turn *sql* into a list of tokens ending with an EOF token."""
    tokens = []
    i = 0
    n = len(sql)

    while i < n:
        c = sql[i]

        if c.isspace():
            i += 1
            continue

        if c == "'":
            start = i
            i += 1
            chars = []
            while i < n:
                ch = sql[i]
                if ch == "'":
                    if i + 1 < n and sql[i + 1] == "'":
                        chars.append("'")
                        i += 2
                    else:
                        i += 1
                        break
                else:
                    chars.append(ch)
                    i += 1
            else:
                raise QueryError("unterminated string literal at position %d" % start)
            tokens.append(Token("STRING", "".join(chars), start, i))
            continue

        if c == '"':
            start = i
            i += 1
            chars = []
            while i < n:
                ch = sql[i]
                if ch == '"':
                    if i + 1 < n and sql[i + 1] == '"':
                        chars.append('"')
                        i += 2
                    else:
                        i += 1
                        break
                else:
                    chars.append(ch)
                    i += 1
            else:
                raise QueryError("unterminated quoted name at position %d" % start)
            tokens.append(Token("QIDENT", "".join(chars), start, i))
            continue

        if c.isdigit() or (c == "." and i + 1 < n and sql[i + 1].isdigit()):
            start = i
            has_dot = False
            while i < n and sql[i].isdigit():
                i += 1
            if i < n and sql[i] == ".":
                has_dot = True
                i += 1
                while i < n and sql[i].isdigit():
                    i += 1
            text = sql[start:i]
            value = float(text) if has_dot else int(text)
            tokens.append(Token("NUMBER", value, start, i))
            continue

        if c.isalpha() or c == "_":
            start = i
            i += 1
            while i < n and (sql[i].isalnum() or sql[i] == "_"):
                i += 1
            text = sql[start:i]
            upper = text.upper()
            if upper in KEYWORDS:
                tokens.append(Token("KEYWORD", upper, start, i))
            else:
                tokens.append(Token("IDENT", text, start, i))
            continue

        two = sql[i:i + 2]
        if two in ("<=", ">=", "<>", "!=", "||"):
            tokens.append(Token("OP", two, i, i + 2))
            i += 2
            continue

        if c in "=<>+-*/(),;":
            tokens.append(Token("OP", c, i, i + 1))
            i += 1
            continue

        raise QueryError("unexpected character %r at position %d" % (c, i))

    tokens.append(Token("EOF", "", n, n))
    return tokens


# ---------------------------------------------------------------------------
# Expression nodes


@dataclass
class Literal:
    value: Any
    text: str = ""


@dataclass
class Name:
    name: str
    text: str = ""


@dataclass
class Star:
    text: str = ""


@dataclass
class Group:
    expr: Any
    text: str = ""


@dataclass
class Unary:
    op: str
    operand: Any
    text: str = ""


@dataclass
class Binary:
    op: str
    left: Any
    right: Any
    text: str = ""


@dataclass
class IsNull:
    operand: Any
    negate: bool
    text: str = ""


@dataclass
class InExpr:
    operand: Any
    items: List[Any]
    negate: bool
    text: str = ""


@dataclass
class Between:
    operand: Any
    low: Any
    high: Any
    negate: bool
    text: str = ""


@dataclass
class Like:
    operand: Any
    pattern: Any
    negate: bool
    text: str = ""


@dataclass
class Func:
    name: str
    args: List[Any]
    text: str = ""


# ---------------------------------------------------------------------------
# Query nodes


@dataclass
class Column:
    expr: Any
    alias: Optional[str] = None


@dataclass
class OrderItem:
    expr: Any
    desc: bool = False


@dataclass
class Query:
    distinct: bool
    columns: List[Column]
    table: str
    where: Any = None
    group_by: List[Any] = field(default_factory=list)
    having: Any = None
    order_by: List[OrderItem] = field(default_factory=list)
    limit: Optional[int] = None
    offset: Optional[int] = None


# ---------------------------------------------------------------------------
# Parser


class Parser:
    def __init__(self, sql, tokens):
        self.sql = sql
        self.tokens = tokens
        self.pos = 0

    # -- token helpers ------------------------------------------------------

    def peek(self, offset=0):
        index = self.pos + offset
        if index >= len(self.tokens):
            index = len(self.tokens) - 1
        return self.tokens[index]

    def advance(self):
        token = self.tokens[self.pos]
        if token.kind != "EOF":
            self.pos += 1
        return token

    def check_kw(self, keyword, offset=0):
        token = self.peek(offset)
        return token.kind == "KEYWORD" and token.value == keyword

    def match_kw(self, keyword):
        if self.check_kw(keyword):
            self.advance()
            return True
        return False

    def expect_kw(self, keyword):
        if not self.check_kw(keyword):
            self._error("expected %s" % keyword, self.peek())
        return self.advance()

    def check_op(self, operator, offset=0):
        token = self.peek(offset)
        return token.kind == "OP" and token.value == operator

    def match_op(self, operator):
        if self.check_op(operator):
            self.advance()
            return True
        return False

    def expect_op(self, operator):
        if not self.check_op(operator):
            self._error("expected %r" % operator, self.peek())
        return self.advance()

    def parse_name(self, what):
        token = self.peek()
        if token.kind not in ("IDENT", "QIDENT"):
            self._error("expected %s" % what, token)
        self.advance()
        return token

    def _error(self, message, token=None):
        if token is None:
            token = self.peek()
        if token.kind == "EOF":
            raise QueryError("%s at end of query" % message)
        raise QueryError("%s at position %d" % (message, token.start))

    def _finish(self, node, start):
        node.text = self.sql[start:self.tokens[self.pos - 1].end]
        return node

    # -- query --------------------------------------------------------------

    def parse(self):
        self.expect_kw("SELECT")
        distinct = self.match_kw("DISTINCT")
        columns = self.parse_columns()
        self.expect_kw("FROM")
        table = self.parse_name("table name").value

        query = Query(distinct=distinct, columns=columns, table=table)

        if self.match_kw("WHERE"):
            query.where = self.parse_expr()

        if self.match_kw("GROUP"):
            self.expect_kw("BY")
            query.group_by = [self.parse_expr()]
            while self.match_op(","):
                query.group_by.append(self.parse_expr())

        if self.match_kw("HAVING"):
            query.having = self.parse_expr()

        if self.match_kw("ORDER"):
            self.expect_kw("BY")
            query.order_by = [self.parse_order_item()]
            while self.match_op(","):
                query.order_by.append(self.parse_order_item())

        if self.match_kw("LIMIT"):
            token = self.peek()
            if token.kind != "NUMBER" or not isinstance(token.value, int):
                self._error("LIMIT must be an integer", token)
            self.advance()
            query.limit = token.value
            if self.match_kw("OFFSET"):
                token = self.peek()
                if token.kind != "NUMBER" or not isinstance(token.value, int):
                    self._error("OFFSET must be an integer", token)
                self.advance()
                query.offset = token.value

        self.match_op(";")
        if self.peek().kind != "EOF":
            self._error("unexpected token", self.peek())

        return query

    def parse_columns(self):
        if self.check_op("*"):
            token = self.advance()
            return [Column(Star(text=self.sql[token.start:token.end]))]

        columns = [self.parse_column()]
        while self.match_op(","):
            columns.append(self.parse_column())
        return columns

    def parse_column(self):
        expr = self.parse_expr()
        alias = None
        if self.match_kw("AS"):
            alias = self.parse_name("column alias").value
        elif self.peek().kind in ("IDENT", "QIDENT"):
            alias = self.advance().value
        return Column(expr, alias)

    def parse_order_item(self):
        expr = self.parse_expr()
        desc = False
        if self.match_kw("DESC"):
            desc = True
        else:
            self.match_kw("ASC")
        return OrderItem(expr, desc)

    # -- expressions --------------------------------------------------------

    def parse_expr(self):
        return self.parse_or()

    def parse_or(self):
        start = self.peek().start
        left = self.parse_and()
        while self.match_kw("OR"):
            right = self.parse_and()
            left = Binary("OR", left, right)
        return self._finish(left, start)

    def parse_and(self):
        start = self.peek().start
        left = self.parse_not()
        while self.match_kw("AND"):
            right = self.parse_not()
            left = Binary("AND", left, right)
        return self._finish(left, start)

    def parse_not(self):
        if self.check_kw("NOT"):
            start = self.peek().start
            self.advance()
            operand = self.parse_not()
            return self._finish(Unary("NOT", operand), start)
        return self.parse_comparison()

    def parse_comparison(self):
        start = self.peek().start
        left = self.parse_additive()
        token = self.peek()

        if token.kind == "OP" and token.value in _COMPARISON_OPS:
            self.advance()
            right = self.parse_additive()
            return self._finish(Binary(token.value, left, right), start)

        if self.match_kw("IS"):
            negate = self.match_kw("NOT")
            self.expect_kw("NULL")
            return self._finish(IsNull(left, negate), start)

        negate = False
        if (self.check_kw("NOT") and self.peek(1).kind == "KEYWORD"
                and self.peek(1).value in ("IN", "BETWEEN", "LIKE")):
            self.advance()
            negate = True

        if self.match_kw("IN"):
            self.expect_op("(")
            items = [self.parse_expr()]
            while self.match_op(","):
                items.append(self.parse_expr())
            self.expect_op(")")
            return self._finish(InExpr(left, items, negate), start)

        if self.match_kw("BETWEEN"):
            low = self.parse_additive()
            self.expect_kw("AND")
            high = self.parse_additive()
            return self._finish(Between(left, low, high, negate), start)

        if self.match_kw("LIKE"):
            pattern = self.parse_additive()
            return self._finish(Like(left, pattern, negate), start)

        return left

    def parse_additive(self):
        start = self.peek().start
        left = self.parse_multiplicative()
        while self.peek().kind == "OP" and self.peek().value in ("+", "-", "||"):
            op = self.advance().value
            right = self.parse_multiplicative()
            left = Binary(op, left, right)
        return self._finish(left, start)

    def parse_multiplicative(self):
        start = self.peek().start
        left = self.parse_unary()
        while self.peek().kind == "OP" and self.peek().value in ("*", "/"):
            op = self.advance().value
            right = self.parse_unary()
            left = Binary(op, left, right)
        return self._finish(left, start)

    def parse_unary(self):
        if self.check_op("-"):
            start = self.peek().start
            self.advance()
            operand = self.parse_unary()
            return self._finish(Unary("-", operand), start)
        return self.parse_primary()

    def parse_primary(self):
        token = self.peek()

        if token.kind in ("NUMBER", "STRING"):
            self.advance()
            return self._finish(Literal(token.value), token.start)

        if token.kind == "KEYWORD":
            if token.value == "NULL":
                self.advance()
                return self._finish(Literal(None), token.start)
            if token.value == "TRUE":
                self.advance()
                return self._finish(Literal(True), token.start)
            if token.value == "FALSE":
                self.advance()
                return self._finish(Literal(False), token.start)
            self._error("expected a value", token)

        if token.kind in ("IDENT", "QIDENT"):
            self.advance()
            if token.kind == "IDENT" and self.check_op("("):
                return self.parse_function(token)
            return Name(token.value, self.sql[token.start:token.end])

        if self.match_op("("):
            start = token.start
            expr = self.parse_expr()
            self.expect_op(")")
            return self._finish(Group(expr), start)

        self._error("expected a value", token)

    def parse_function(self, name_token):
        start = name_token.start
        self.expect_op("(")
        args = []

        if self.check_op("*"):
            token = self.advance()
            args.append(Star(text=self.sql[token.start:token.end]))
            self.expect_op(")")
        else:
            if not self.check_op(")"):
                args.append(self.parse_expr())
                while self.match_op(","):
                    args.append(self.parse_expr())
            self.expect_op(")")

        return self._finish(Func(name_token.value.lower(), args), start)


def parse(sql):
    """Parse *sql* and return a :class:`Query`."""
    if not isinstance(sql, str):
        raise QueryError("query must be a string")
    return Parser(sql, tokenize(sql)).parse()

"""Loading, validation, and execution for minisql."""

import csv
import re
from dataclasses import dataclass
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from functools import cmp_to_key
from typing import Any, Dict, List, Optional, Tuple

from . import _sql
from ._errors import QueryError


AGGREGATES = {"count", "sum", "avg", "min", "max"}
SCALAR_ARITY = {
    "lower": (1, 1),
    "upper": (1, 1),
    "length": (1, 1),
    "abs": (1, 1),
    "round": (1, 2),
    "coalesce": (1, None),
}

_INTEGER_RE = re.compile(r"-?[0-9]+\Z")
_DECIMAL_RE = re.compile(r"(?:-?[0-9]+\.[0-9]*|-?[0-9]*\.[0-9]+)\Z")


class Result:
    """The result of a query: output column names and row tuples."""

    __slots__ = ("columns", "rows")

    def __init__(self, columns, rows):
        self.columns = list(columns)
        self.rows = list(rows)

    def __repr__(self):
        return "Result(columns=%r, rows=%r)" % (self.columns, self.rows)


# ---------------------------------------------------------------------------
# Tables


@dataclass
class Table:
    header: List[str]
    rows: List[Tuple[Any, ...]]
    index: Dict[str, int]


def _convert_field(field):
    if field == "":
        return None
    if _INTEGER_RE.fullmatch(field):
        return int(field)
    if _DECIMAL_RE.fullmatch(field):
        return float(field)
    return field


def _load_table(directory, name):
    import os

    path = os.path.join(directory, name + ".csv")
    try:
        with open(path, "r", newline="", encoding="utf-8-sig") as handle:
            reader = csv.reader(handle)
            try:
                header = next(reader)
            except StopIteration:
                raise QueryError("table %r has no header" % name)
            rows = [tuple(_convert_field(field) for field in record)
                    for record in reader]
    except QueryError:
        raise
    except FileNotFoundError:
        raise QueryError("unknown table: %s" % name)
    except OSError as exc:
        raise QueryError("cannot read table %r: %s" % (name, exc))
    except csv.Error as exc:
        raise QueryError("cannot read table %r: %s" % (name, exc))

    width = len(header)
    normalised = []
    for row in rows:
        if len(row) < width:
            row = row + (None,) * (width - len(row))
        elif len(row) > width:
            row = row[:width]
        normalised.append(row)

    index = {}
    for i, column in enumerate(header):
        index.setdefault(column.lower(), i)

    return Table(header, normalised, index)


# ---------------------------------------------------------------------------
# Expression helpers


def _children(expr):
    if isinstance(expr, _sql.Group):
        yield expr.expr
    elif isinstance(expr, _sql.Unary):
        yield expr.operand
    elif isinstance(expr, _sql.Binary):
        yield expr.left
        yield expr.right
    elif isinstance(expr, _sql.IsNull):
        yield expr.operand
    elif isinstance(expr, _sql.InExpr):
        yield expr.operand
        for item in expr.items:
            yield item
    elif isinstance(expr, _sql.Between):
        yield expr.operand
        yield expr.low
        yield expr.high
    elif isinstance(expr, _sql.Like):
        yield expr.operand
        yield expr.pattern
    elif isinstance(expr, _sql.Func):
        for arg in expr.args:
            yield arg


def _has_aggregate(expr):
    if isinstance(expr, _sql.Func) and expr.name in AGGREGATES:
        return True
    return any(_has_aggregate(child) for child in _children(expr))


def _value_key(value):
    if value is None:
        return ("null",)
    if isinstance(value, bool):
        return ("bool", value)
    if isinstance(value, (int, float)):
        return ("number", value)
    if isinstance(value, str):
        return ("string", value)
    return ("other", repr(value))


def _expr_key(expr):
    if isinstance(expr, _sql.Literal):
        return ("literal", _value_key(expr.value))
    if isinstance(expr, _sql.Name):
        return ("name", expr.name.lower())
    if isinstance(expr, _sql.Star):
        return ("star",)
    if isinstance(expr, _sql.Group):
        return _expr_key(expr.expr)
    if isinstance(expr, _sql.Unary):
        return ("unary", expr.op, _expr_key(expr.operand))
    if isinstance(expr, _sql.Binary):
        op = expr.op
        if op == "<>":
            op = "!="
        return ("binary", op, _expr_key(expr.left), _expr_key(expr.right))
    if isinstance(expr, _sql.IsNull):
        return ("isnull", expr.negate, _expr_key(expr.operand))
    if isinstance(expr, _sql.InExpr):
        return ("in", expr.negate, _expr_key(expr.operand),
                tuple(_expr_key(item) for item in expr.items))
    if isinstance(expr, _sql.Between):
        return ("between", expr.negate, _expr_key(expr.operand),
                _expr_key(expr.low), _expr_key(expr.high))
    if isinstance(expr, _sql.Like):
        return ("like", expr.negate, _expr_key(expr.operand),
                _expr_key(expr.pattern))
    if isinstance(expr, _sql.Func):
        return ("func", expr.name, tuple(_expr_key(arg) for arg in expr.args))
    return ("unknown", repr(expr))


# ---------------------------------------------------------------------------
# Static validation


def _validate_expr(expr, table, where=False, in_aggregate=False,
                   allow_aggregate=True):
    if isinstance(expr, _sql.Star):
        raise QueryError("'*' is only allowed in COUNT(*) or after SELECT")

    if isinstance(expr, _sql.Name):
        if expr.name.lower() not in table.index:
            raise QueryError("unknown column: %s" % expr.name)
        return

    if isinstance(expr, _sql.Func):
        name = expr.name

        if name in AGGREGATES:
            if where:
                raise QueryError("aggregate %s is not allowed in WHERE"
                                 % name.upper())
            if not allow_aggregate:
                raise QueryError("aggregate %s is not allowed here"
                                 % name.upper())
            if in_aggregate:
                raise QueryError("aggregates cannot be nested")

            if len(expr.args) != 1:
                raise QueryError("%s takes exactly one argument"
                                 % name.upper())

            argument = expr.args[0]
            if isinstance(argument, _sql.Star):
                if name != "count":
                    raise QueryError("'*' is only allowed in COUNT(*)")
                return
            _validate_expr(argument, table, where, True, allow_aggregate)
            return

        arity = SCALAR_ARITY.get(name)
        if arity is None:
            raise QueryError("unknown function: %s" % expr.name)

        minimum, maximum = arity
        if len(expr.args) < minimum or (maximum is not None
                                        and len(expr.args) > maximum):
            raise QueryError("wrong number of arguments for %s"
                             % name.upper())

        for argument in expr.args:
            if isinstance(argument, _sql.Star):
                raise QueryError("'*' is only allowed in COUNT(*)")
            _validate_expr(argument, table, where, in_aggregate,
                           allow_aggregate)
        return

    for child in _children(expr):
        _validate_expr(child, table, where, in_aggregate, allow_aggregate)


def _check_grouped(expr, group_keys):
    if _expr_key(expr) in group_keys:
        return
    if isinstance(expr, _sql.Func) and expr.name in AGGREGATES:
        return
    if isinstance(expr, _sql.Name):
        raise QueryError(
            "column %s must appear in GROUP BY or be used in an aggregate"
            % expr.name)
    for child in _children(expr):
        _check_grouped(child, group_keys)


# ---------------------------------------------------------------------------
# Evaluation


@dataclass
class _Context:
    table: Table
    row: Optional[Tuple[Any, ...]]
    group_rows: Optional[List[Tuple[Any, ...]]] = None

    def with_row(self, row):
        return _Context(self.table, row, self.group_rows)


def _is_number(value):
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def _type_name(value):
    if value is None:
        return "NULL"
    if isinstance(value, bool):
        return "boolean"
    if isinstance(value, (int, float)):
        return "number"
    if isinstance(value, str):
        return "string"
    return type(value).__name__


def _ensure_number(value, operation):
    if not _is_number(value):
        raise QueryError("%s requires numbers, not %s"
                         % (operation, _type_name(value)))


def _compare_values(left, right):
    if _is_number(left) and _is_number(right):
        return (left > right) - (left < right)
    if isinstance(left, str) and isinstance(right, str):
        return (left > right) - (left < right)
    if isinstance(left, bool) and isinstance(right, bool):
        return (left > right) - (left < right)
    raise QueryError("cannot compare %s with %s"
                     % (_type_name(left), _type_name(right)))


def _and3(left, right):
    if left is False or right is False:
        return False
    if left is None or right is None:
        return None
    return True


def _or3(left, right):
    if left is True or right is True:
        return True
    if left is None or right is None:
        return None
    return False


def _logical_operand(value, operation):
    if value is None or isinstance(value, bool):
        return value
    raise QueryError("%s requires boolean operands, not %s"
                     % (operation, _type_name(value)))


def _to_text(value):
    if isinstance(value, bool):
        return "true" if value else "false"
    return str(value)


def _like_regex(pattern):
    parts = ["\\A"]
    for char in pattern:
        if char == "%":
            parts.append(".*")
        elif char == "_":
            parts.append(".")
        else:
            parts.append(re.escape(char))
    parts.append("\\Z")
    return re.compile("".join(parts), re.DOTALL)


def _round_value(value, places):
    _ensure_number(value, "ROUND")
    if not isinstance(places, int) or isinstance(places, bool):
        raise QueryError("ROUND places must be an integer")

    decimal_value = Decimal(str(value))
    quantum = Decimal(1).scaleb(-places)
    try:
        result = decimal_value.quantize(quantum, rounding=ROUND_HALF_UP)
    except InvalidOperation:
        raise QueryError("ROUND result is out of range")
    return result


def _eval_aggregate(expr, context):
    name = expr.name
    argument = expr.args[0]
    rows = context.group_rows if context.group_rows is not None else []

    if isinstance(argument, _sql.Star):
        return len(rows)

    values = []
    for row in rows:
        value = _eval(argument, context.with_row(row))
        if value is not None:
            values.append(value)

    if name == "count":
        return len(values)
    if not values:
        return None

    if name in ("sum", "avg"):
        for value in values:
